const RECORDS=Object.freeze(DATA.records.map(x=>Object.freeze(x)));
const CONCEPTS=Object.freeze(DATA.concepts.map(x=>Object.freeze(x)));

function letters(s){return String(s||"").toUpperCase().replace(/[^A-Z]/g,"");}
function reverse(s){return Array.from(String(s)).reverse().join("");}
function value(s){return [...letters(s)].reduce((sum,c)=>sum+((c.charCodeAt(0)-65)%9+1),0);}
function digitalRoot(n){if(!Number.isSafeInteger(n)||n<0)throw RangeError("nonnegative safe integer required");return n===0?0:1+(n-1)%9;}
function explainMirror(s){const original=String(s);return {original,reversed:reverse(original),restored:reverse(reverse(original)),invariant:reverse(reverse(original))===original,letterSum:value(original),reverseLetterSum:value(reverse(original)),digitalRoot:digitalRoot(value(original))};}
function find(query,options={}){const needle=String(query||"").trim().toLowerCase(),limit=Math.min(300,Math.max(1,Number(options.limit)||30));return [...RECORDS,...CONCEPTS].filter(r=>(!options.family||r.family===options.family)&&(!needle||[r.title,r.equation||"",r.group,r.id].join(" ").toLowerCase().includes(needle))).slice(0,limit).map(x=>({...x}));}
function enrich(E,state) {
 if(!E||typeof E.addNode!=="function"||typeof E.attach!=="function")throw Error("Octopus root engine required");
 let s=state,added=0,linked=0;
 const all=[...RECORDS,...CONCEPTS];
 for(const r of all){
  if(s.nodes.some(n=>n.id===r.id))continue;
  const entry=E.addNode(s,{id:r.id,label:r.title.slice(0,100),kind:r.kind||"formula",origin:(r.source+" | "+r.group).slice(0,200),glyphs:""});
  if(entry.ok){s=entry.state;added++;}
 }
 for(const r of all){
  if(!s.nodes.some(n=>n.id===r.id))continue;
  const to=r.id;
  if(s.edges.some(e=>e.from==="core:middle"&&e.to===to&&e.type==="symbolic"))continue;
  const linkedEdge=E.attach(s,{from:"core:middle",to,type:"symbolic",note:"Root codex index / "+r.group+" / "+r.family});
  if(linkedEdge.ok){s=linkedEdge.state;linked++;}
 }
 return {state:s,added,linked};
}
return Object.freeze({VERSION:DATA.version,RECORDS,CONCEPTS,letters,reverse,value,digitalRoot,explainMirror,find,enrich});

